{
  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C13"],
      "claim": "The tryptophan-derived radiotracer 5-[18F]FEHTrp showed low brain uptake (0.84 %ID/g) in mice, directly demonstrating that this indole/tryptophan scaffold does not confer meaningful CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "Carfilzomib, a high-molecular-weight amide-rich peptidomimetic, failed to suppress brain proteasome activity after IV dosing in rats, indicating poor BBB passage and supporting a fail prediction for the query's amide-rich, high-MW structure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "The related tryptophan analogue [18F]FPOTrp also showed low brain uptake (1.16 %ID/g) in mice, reinforcing the poor CNS penetration phenotype of tryptophan-derived agents.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "CP 96,345, which shares the 2-methoxybenzylamine and cationic amine features with the query, showed minimal brain uptake in guinea pigs and was concluded to be excluded by the BBB, directly supporting a fail prediction.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "CI988, a tryptophan-containing dipeptoid, was undetectable in rat brain after IV dosing, supporting that tryptophan/amide peptidomimetics with high molecular weight have inadequate CNS access.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "High-transfer direct evidence from tryptophan-derived and amide-rich peptidomimetic analogues consistently shows poor brain uptake or BBB impermeability. The query's high molecular weight, basic piperidines, and likely cationic/efflux liabilities align with these measured phenotypes, so the prediction is fail.",
  "evidence_gaps": [
    "No direct brain/plasma or CSF measurement exists for the exact query molecule.",
    "Efflux transporter status of the query is inferred but not directly measured.",
    "Low-transfer permeable analogues exist, but their structural relevance is too weak to override the high-transfer impermeability evidence."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

